//! One number per compile mode that changes if any generated byte changes.
//!
//! For proving a refactor is output-preserving. The compatibility corpus answers
//! "does rsvelte match official"; this answers the different question "does this
//! revision match the previous revision", which is what a change claiming to be
//! observationally equivalent has to clear. Run it on the revision before the
//! change and on the revision after, and compare.
//!
//! Compiling both `client` and `server` in both `dev` and release is deliberate:
//! a gate that feeds runes detection can move `dev`-only output (extra
//! validation calls) without touching release output, so checking one mode would
//! pass a change that alters the other.
//!
//! `failed` is printed beside the hash because a change that makes compilation
//! *fail* also changes the hash, and the two need to be told apart -- an
//! unchanged failure count with an unchanged hash is the claim; a moved failure
//! count is a regression wearing the same clothes.
//!
//! ```text
//! cargo run --release -p rsvelte_devtools --bin corpus_output_hash -- <dir>...
//! ```

use std::hash::{Hash, Hasher};
use std::path::{Path, PathBuf};

use rsvelte_core::{CompileOptions, GenerateMode, compile};

fn collect(dir: &Path, out: &mut Vec<PathBuf>) {
    let Ok(entries) = std::fs::read_dir(dir) else {
        return;
    };
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            collect(&path, out);
        } else if path.extension().is_some_and(|e| e == "svelte") {
            out.push(path);
        }
    }
}

fn main() {
    let roots: Vec<PathBuf> = std::env::args().skip(1).map(PathBuf::from).collect();
    if roots.is_empty() {
        eprintln!("usage: corpus_output_hash <dir>...");
        std::process::exit(1);
    }

    let mut files = Vec::new();
    for root in &roots {
        collect(root, &mut files);
    }
    // Sorted so the hash is over an order that does not depend on the
    // filesystem's enumeration order; otherwise two runs on the same tree could
    // disagree for a reason that has nothing to do with the compiler.
    files.sort();
    if files.is_empty() {
        eprintln!("no .svelte files under the given roots");
        std::process::exit(1);
    }

    println!("{} files", files.len());
    for (label, generate, dev) in [
        ("client", GenerateMode::Client, false),
        ("client-dev", GenerateMode::Client, true),
        ("server", GenerateMode::Server, false),
        ("server-dev", GenerateMode::Server, true),
    ] {
        let mut hasher = rustc_hash::FxHasher::default();
        let mut bytes = 0usize;
        let mut failed = 0u64;
        for path in &files {
            let Ok(source) = std::fs::read_to_string(path) else {
                continue;
            };
            // The path goes into the hash as well, so that two files swapping
            // their outputs would not cancel out.
            path.to_string_lossy().hash(&mut hasher);
            match compile(
                &source,
                CompileOptions {
                    generate,
                    dev,
                    ..Default::default()
                },
            ) {
                Ok(result) => {
                    result.js.code.hash(&mut hasher);
                    result.css.as_ref().map(|c| &c.code).hash(&mut hasher);
                    bytes += result.js.code.len();
                }
                Err(_) => {
                    failed += 1;
                    "ERR".hash(&mut hasher);
                }
            }
        }
        println!(
            "{label:<12} hash {:016x}   jsBytes {bytes:>10}   failed {failed}",
            hasher.finish()
        );
    }
}
